(() => {
 const $=id=>document.getElementById(id), svgNS="http://www.w3.org/2000/svg";
 const categories=["All","Primary batteries","Secondary batteries","Fuel cells","Other / special technologies"];
 let group="All",query="",active=DB.find(x=>x.id===location.hash.slice(1))||DB[0],mode="discharge",paused=matchMedia("(prefers-reduced-motion: reduce)").matches,elapsed=0,last=0;
 const wire=$("wire"),ionPath=$("ionPath"),ions=[],electrons=[];
 function particle(parent,color,label,r){const g=document.createElementNS(svgNS,"g"),c=document.createElementNS(svgNS,"circle"),t=document.createElementNS(svgNS,"text");c.setAttribute("r",r);c.setAttribute("fill",color);c.setAttribute("stroke","#fff");c.setAttribute("stroke-width","2");t.setAttribute("text-anchor","middle");t.setAttribute("dominant-baseline","central");t.setAttribute("fill","#fff");t.setAttribute("font-size",label==="e⁻"?"13":"11");t.setAttribute("font-weight","700");t.textContent=label;g.append(c,t);parent.append(g);return {g,t};}
 for(let i=0;i<3;i++){ions.push(particle($("ions"),"#df914a","Li⁺",17));electrons.push(particle($("electrons"),"#257ba6","e⁻",16));}
 function setText(id,value){$(id).textContent=value;}
 function filtered(){return DB.filter(x=>(group==="All"||x.group===group)&&[x.name,x.uses,x.materials,x.carrier,...MAKERS[x.id].map(m=>m[0])].join(" ").toLocaleLowerCase().includes(query));}
 function drawFilters(){const container=$("filters");container.replaceChildren();categories.forEach(c=>{const b=document.createElement("button");b.type="button";b.textContent=c;b.setAttribute("aria-pressed",String(group===c));b.addEventListener("click",()=>{group=c;drawFilters();renderList();});container.append(b);});}
 function renderList(){const list=$("items"),results=filtered();list.replaceChildren();setText("count",results.length+" technologies");if(!results.length){const e=document.createElement("p");e.className="empty";e.textContent=group==="Other / special technologies"&&!query?"All 25 technologies currently listed are primary batteries, secondary batteries or fuel cells. Rechargeable flow batteries belong to secondary batteries.":"No results. Try another material or technology name.";list.append(e);return;}results.forEach(x=>{const b=document.createElement("button");b.type="button";b.className="item";b.setAttribute("role","option");b.setAttribute("aria-selected",String(active.id===x.id));const n=document.createElement("span"),s=document.createElement("small");n.textContent=x.name;s.textContent=x.group;b.append(n,s);b.addEventListener("click",()=>select(x));list.append(b);});}
 function select(x){active=x;mode="discharge";elapsed=0;history.replaceState(null,"","#"+x.id);renderList();renderDetail();}
 function renderDetail(){const x=active;$("productDetail").innerHTML=renderProduct(x.id);$("manufacturerDetail").innerHTML=renderMakers(x.id);setText("category",x.group+" / "+x.stage);setText("name",x.name);setText("stage",x.stage);setText("principle",x.principle);$("detailLink").href="technology/"+x.id+"/";setText("leftLabel",x.left);setText("rightLabel",x.right);setText("electrolyte",x.electrolyte);setText("reaction",x.reaction);setText("pros",x.pros);setText("cons",x.cons);setText("materials",x.materials);setText("uses",x.uses);setText("sales",x.sales);setText("price",x.price);setText("priceNote",x.priceNote||"");setText("ionLegend",x.carrier);setText("electrolyteLabel",x.group==="Fuel cells"?"Electrolyte membrane":x.subtype==="Flow batteries"?"Electrolyte solution / separator":"Electrolyte / separator");setText("leftFoot",x.group==="Fuel cells"?"Fuel electrode":"Anode · during discharge");setText("rightFoot",x.group==="Fuel cells"?"Air electrode":"Cathode · during discharge");
  $("charge").disabled=x.group==="Primary batteries"||x.group==="Fuel cells";const src=$("sources");src.replaceChildren();x.sources.forEach(key=>{const a=document.createElement("a");a.href=SOURCES[key].url;a.target="_blank";a.rel="noopener";a.textContent=SOURCES[key].name+" ↗";src.append(a);});updateMode();
 }
 function updateMode(){const x=active,charging=mode==="charge";$("discharge").setAttribute("aria-pressed",String(!charging));$("charge").setAttribute("aria-pressed",String(charging));setText("loadText",charging?"Charger":x.group==="Fuel cells"?"Power output":"Powering a load");
  setText("simCaption",x.group==="Fuel cells"?"Generates while fuel and oxygen are supplied. It does not store electricity internally like a rechargeable battery.":x.group==="Primary batteries"?"Discharge pathway for a single-use cell. Ordinary products must not be recharged.":charging?"An external source drives electrons into the battery. Ion movement also reverses relative to discharge.":"Ions move through the electrolyte; electrons flow through the external circuit.");
  ions.forEach(p=>p.t.textContent=x.carrier);draw();
 }
 function position(g,path,p,reverse){const point=path.getPointAtLength(path.getTotalLength()*(reverse?1-p:p));g.setAttribute("transform",`translate(${point.x} ${point.y})`);}
 function draw(){if(!active)return;const ionReverse=(active.direction==="left")!==(mode==="charge"),electronReverse=mode==="charge";for(let i=0;i<3;i++){const p=(elapsed/4300+i/3)%1;position(ions[i].g,ionPath,p,ionReverse);position(electrons[i].g,wire,p,electronReverse);}}
 function frame(t){if(last&&!paused)elapsed+=Math.min(80,t-last);last=t;draw();requestAnimationFrame(frame);}
 $("search").addEventListener("input",e=>{query=e.target.value.trim().toLocaleLowerCase();renderList();});
 $("discharge").addEventListener("click",()=>{mode="discharge";elapsed=0;updateMode();});
 $("charge").addEventListener("click",()=>{if($("charge").disabled)return;mode="charge";elapsed=0;updateMode();});
 $("pause").addEventListener("click",()=>{paused=!paused;$("pause").textContent=paused?"▶":"Ⅱ";$("pause").setAttribute("aria-pressed",String(paused));$("pause").setAttribute("aria-label",paused?"Play animation":"Pause animation");});
 if(paused){$("pause").textContent="▶";$("pause").setAttribute("aria-pressed","true");$("pause").setAttribute("aria-label","Play animation");}
 $("evShareReference").innerHTML=renderEVShare();drawFilters();renderList();renderDetail();requestAnimationFrame(frame);
})();
